use std::process::Command;
use std::os::unix::ffi::OsStrExt;
use std::ffi::OsStr;

const B: &str = "/workspace/dataset/test4_executable";

fn run(arg: &[u8]) -> [u8;4] {
    let o = Command::new(B).arg(OsStr::from_bytes(arg)).output().expect("spawn");
    let s = String::from_utf8_lossy(&o.stdout);
    let mut r = [9u8;4];
    for (i,l) in s.lines().enumerate().take(4) {
        r[i] = if l.trim()=="1" {1} else if l.trim()=="0" {0} else {9};
    }
    r
}

struct Rng(u64);
impl Rng { fn next(&mut self)->u64 { let mut x=self.0; x^=x<<13; x^=x>>7; x^=x<<17; self.0=x; x } }

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();
    let mut bad = 0usize; let mut n = 0usize;

    if mode == "repeat" {
        // every byte value repeated at every length 1..=70
        for b in 1u16..=255 {
            for len in 1usize..=70 {
                let v = vec![b as u8; len];
                let r = run(&v); n+=1;
                let expect = if len>=1 && len<=63 {1} else {0};
                if r[1]!=expect { println!("CE byte=0x{:02x} len={} out={:?}", b, len, r); bad+=1; }
            }
        }
    } else if mode == "fuzz" {
        let mut rng = Rng(0x12345678deadbeef);
        for _ in 0..40000 {
            let len = (rng.next() % 301) as usize; // 0..300
            let mut v = Vec::with_capacity(len);
            for _ in 0..len { let mut c = (rng.next() % 256) as u8; if c==0 { c=1; } v.push(c); }
            let r = run(&v); n+=1;
            let expect = if v.len()>=1 && v.len()<=63 {1} else {0};
            if r[1]!=expect { println!("CE len={} bytes={:02x?} out={:?}", v.len(), &v[..v.len().min(80)], r); bad+=1; if bad>10 {break;} }
        }
    } else if mode == "utf8" {
        // random valid-UTF8 strings of varying codepoint sizes, lengths in bytes 55..75
        let mut rng = Rng(0xabcdef0123456789);
        let pool: Vec<char> = vec!['a','Z','0','-','.','_','é','ß','中','例','😀','\u{00ad}','\u{200c}','\u{3002}','\u{ff21}','\u{0301}','\u{05d0}','\u{0627}','\u{0966}','\u{1e9e}','\u{212a}','\u{fb00}'];
        for _ in 0..20000 {
            let ncp = (rng.next() % 40) as usize;
            let mut s = String::new();
            for _ in 0..ncp { s.push(pool[(rng.next() as usize) % pool.len()]); }
            let v = s.as_bytes().to_vec();
            let r = run(&v); n+=1;
            let expect = if v.len()>=1 && v.len()<=63 {1} else {0};
            if r[1]!=expect { println!("CE utf8 bytes={} cps={} s={:?} out={:?}", v.len(), s.chars().count(), s, r); bad+=1; if bad>10 {break;} }
        }
    } else if mode == "three" {
        // exhaustive 3-byte over a reduced but structured space: b1 in all, b2,b3 in a set of 25 representatives
        let reps: Vec<u8> = vec![0x01,0x09,0x0a,0x0d,0x20,0x21,0x2d,0x2e,0x2f,0x30,0x3a,0x41,0x5f,0x61,0x7a,0x7f,0x80,0xbf,0xc0,0xc2,0xe0,0xe4,0xf0,0xf4,0xff];
        for &b1 in &reps { for &b2 in &reps { for b3 in 1u16..=255 {
            let v = vec![b1,b2,b3 as u8];
            let r = run(&v); n+=1;
            if r[1]!=1 { println!("CE 3byte {:02x} {:02x} {:02x} out={:?}", b1,b2,b3, r); bad+=1; }
        }}}
    }
    println!("mode={} tested={} counterexamples={}", mode, n, bad);
}
